#!/usr/bin/env node
'use strict';
/**
 * scripts/build-research-page.js — rebuild the Market Study report bodies in
 * research.html from the ACTIVE BRAND'S own record.
 *
 * research.html shipped with four hand-written `<div class="ms-report">`
 * blocks that were a word-swapped copy of a DIFFERENT brand's analyst study
 * (tea/coffee/ayurveda sizing and incumbents, relabelled "sneaker"). Because
 * the page is static and brand-blind, every workspace saw it - a health-media
 * brand was shown sneaker tonnage in tons and Brooke Bond as a competitor.
 *
 * The bodies are now generated by scripts/market-study-content.js, which reads
 * `brand.market_study` and emits an explicit DATA REQUIRED state for any region
 * the brand has no sourced study for. The page additionally re-renders client
 * side for the signed-in user's ACTIVE brand, so switching brand switches the
 * study (or clears it) without a rebuild.
 *
 * Run: node scripts/build-research-page.js   (wired into npm run build)
 */
const fs = require('fs');
const path = require('path');
const msc = require('./market-study-content.js');

const ROOT = path.join(__dirname, '..');
const FILE = path.join(ROOT, 'research.html');
const REGION_ORDER = ['US', 'UK', 'Global', 'India'];

let html = fs.readFileSync(FILE, 'utf8');
const brand = msc.defaultBrand();

// Replace the Nth ms-report block body with the generated report for region N.
let idx = 0;
let out = '';
let cursor = 0;
const OPEN = '<div class="ms-report"';
while (true) {
  const start = html.indexOf(OPEN, cursor);
  if (start < 0 || idx >= REGION_ORDER.length) break;
  const bodyStart = html.indexOf('>', start) + 1;
  // walk to the matching close tag
  let depth = 1;
  let p = bodyStart;
  while (p < html.length && depth > 0) {
    const nextOpen = html.indexOf('<div', p);
    const nextClose = html.indexOf('</div>', p);
    if (nextClose < 0) break;
    if (nextOpen >= 0 && nextOpen < nextClose) { depth++; p = nextOpen + 4; }
    else { depth--; p = nextClose + 6; }
  }
  const bodyEnd = p - 6; // before the final </div>
  const region = REGION_ORDER[idx];
  const body = `\n<!-- generated by scripts/build-research-page.js from brand.market_study (${region}) -->\n`
    + msc.reportInnerHTML(region, brand) + '\n';
  out += html.slice(cursor, bodyStart) + body;
  cursor = bodyEnd;
  idx++;
}
out += html.slice(cursor);
html = out;

// ── Client-side: follow the signed-in user's ACTIVE brand ───────────────────
// The runtime that re-renders the tabs and panels for the ACTIVE brand (its
// regions, its home market, its record) lives IN research.html, once. It used
// to be duplicated here as a template string and inserted only when absent,
// which meant two copies that could drift; now the build asserts the page
// still carries it, so a stripped page fails the build instead of shipping
// four static tenant-zero panels to every brand.
if (html.indexOf('Market Study follows the ACTIVE brand') < 0) {
  throw new Error('research.html: the active-brand region runtime is missing (marker "Market Study follows the ACTIVE brand"). Restore it before building.');
}

fs.writeFileSync(FILE, html, 'utf8');
console.log(`research.html: rebuilt ${idx} region study blocks for ${brand.name}` +
  ` (with study: ${REGION_ORDER.filter((r) => msc.studyFor(brand, r)).join(', ') || 'none'})`);
